const UUID_RE = '[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}';
const HEX8_RE = '[0-9a-f]{8}';
const SEQ_RE = '[1-9][0-9]*';

const CURRENT = new RegExp(`^(${UUID_RE})\\/(${SEQ_RE})$`);
const LEGACY  = new RegExp(`^(${HEX8_RE})\\/(${SEQ_RE})$`);

function parseTaskId(id) {
  if (typeof id !== 'string') return null;

  let m = id.match(CURRENT);
  if (m) return { session: m[1], seq: parseInt(m[2], 10), legacy: false };

  m = id.match(LEGACY);
  if (m) return { session: `legacy/${m[1]}`, seq: parseInt(m[2], 10), legacy: true };

  return null;
}

module.exports = { parseTaskId };

